/* @socom-skeleton body GetMesh__Q23zdb5CNodeFv */
zdb::CMesh * zdb::CNode::GetMesh()
	{
		CVisual* mesh = NULL;

		if (!m_visual.empty())
		{
			mesh = *m_visual.data();
		}

		if (!mesh || !mesh->m_has_lods)
		{
			mesh = NULL;
		}

		return static_cast<CMesh*>(mesh);
	}

