/* @socom-skeleton body SetModel__Q23zdb5CNodeFPQ23zdb6CModel */
namespace zdb {
bool CNode::SetModel(CModel* model)
	{
		if (m_type != (u32)TYPE::CHILD || m_type != (u32)TYPE::INSTANCE)
		{
			return false;
		}

		if (model)
			DeleteChildren();

		AddChild(model);

		char* name;
		m_model = model;

		if (!model)
			name = NULL;
		else
			name = model->m_name;

		SetModelname(name);
		return true;
	}
}
